style.css:
/* This is a CSS comment */
body {
  background-color: lightblue; /* Sets the background color */
  font-family: Arial, sans-serif; /* Sets the font style */
  color: darkblue; /* Sets the text color */
}

h1 {
  text-align: center; /* Centers the heading */
  font-size: 2em; /* Sets the font size */
}

p {
  line-height: 1.5; /* Adjusts the spacing between lines */
  margin: 20px; /* Adds space around the paragraph */
}
